"""Plain text contact sheet for substitute teachers."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError

# ---
def contact_rows(students: List[Student]) -> List[str]:
    """One aligned row per student, sorted by name."""
    if not students:
        raise ProjectError("no students to list")
    ordered = sorted(
        students, key=lambda item: item.display_name
    )
    for item in ordered:
        if not item.email:
            raise ProjectError(
                f"no email for {item.display_name}"
            )
    name_width = max(
        len(item.display_name) for item in ordered
    )
    section_width = max(
        len(item.section) for item in ordered
    )
    return [
        f"{item.display_name:<{name_width}}  "
        f"{item.section:<{section_width}}  {item.email}"
        for item in ordered
    ]
